// ============================================================================
// TRUTHFUL SITEMAP LASTMOD
// Resolves per-route last-modified dates from src/lib/seo/contentDates.json
// (generated by scripts/generate-content-dates.mjs as a `prebuild` step, from
// git history — the Frame-Cipher convention).
// Resolution: exact route match → longest prefix match (`/services/*`) → null.
// ============================================================================

import fs from "node:fs";
import path from "node:path";

interface ContentDates {
  generatedAt: number;
  routes: Record<string, string>;
}

let cached: ContentDates | null = null;

function loadDates(): ContentDates | null {
  if (cached) return cached;
  try {
    const file = path.resolve(process.cwd(), "src/lib/seo/contentDates.json");
    cached = JSON.parse(fs.readFileSync(file, "utf8")) as ContentDates;
    return cached;
  } catch {
    return null;
  }
}

/** ISO lastmod for a route, or undefined when the map has no useful entry. */
export function routeLastmod(route: string): string | undefined {
  const dates = loadDates();
  if (!dates?.routes) return undefined;

  const exact = dates.routes[route];
  if (exact) return exact;

  // Longest matching wildcard prefix: "/services/*" covers "/services/seo".
  const prefixCandidates = Object.keys(dates.routes).filter((key) =>
    key.endsWith("/*"),
  );
  prefixCandidates.sort((a, b) => b.length - a.length);
  for (const wildcard of prefixCandidates) {
    if (route === wildcard.slice(0, -1)) return undefined; // key itself, not a child
    if (route.startsWith(wildcard.slice(0, -1))) return dates.routes[wildcard];
  }
  return undefined;
}
